/**
 * Decoding negotiated blank-node origins must not change when a result blocks: a background result waits for its header
 * (tuples) or its first statement (graphs), and that wait belongs to whoever reads the result, not to evaluate().
 */
// A regression must fail, not hang: a blocked read is cut off rather than waiting for a server that never answers.
@Timeout(value = 2, unit = TimeUnit.MINUTES, threadMode = Timeout.ThreadMode.SEPARATE_THREAD)
class BNodeOriginTransportStreamingTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final Duration PROMPTLY = Duration.ofSeconds(10);

	private static class Factory extends SimpleValueFactory implements StoredBNodeIdResolver {
		private final Set<String> stored = new HashSet<>();

		@Override
		public boolean hasStoredBNodeId(String id) {
			return stored.contains(id);
		}
	}

	private final ExecutorService executor = Executors.newCachedThreadPool();

	@AfterEach
	void shutDown() {
		executor.shutdownNow();
	}

	@Test
	void mappedTupleResultsReadTheirBindingNamesOnlyWhenAsked() {
		AtomicInteger reads = new AtomicInteger();
		TupleQueryResult source = new IteratingTupleQueryResult(List.of("node"), List.of(row("node", VF.createIRI(
				"urn:a")))) {
			@Override
			public List<String> getBindingNames() {
				reads.incrementAndGet();
				return super.getBindingNames();
			}
		};

		TupleQueryResult mapped = BNodeOriginTransport.map(source, value -> value);

		assertThat(reads).as("mapping reads no header").hasValue(0);
		assertThat(mapped.getBindingNames()).containsExactly("node");
		assertThat(mapped.getBindingNames()).containsExactly("node");
		assertThat(reads).as("each read asks the source, which may still be waiting for its header").hasValue(2);
		assertThat(mapped.next().getValue("node")).isEqualTo(VF.createIRI("urn:a"));
	}

	@Test
	void mappedGraphResultsReadTheirNamespacesOnlyWhenAsked() {
		AtomicInteger reads = new AtomicInteger();
		Statement statement = VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"));
		GraphQueryResult source = new IteratingGraphQueryResult(Map.of("ex", "urn:ex:"), List.of(statement)) {
			@Override
			public Map<String, String> getNamespaces() {
				reads.incrementAndGet();
				return super.getNamespaces();
			}
		};

		GraphQueryResult mapped = BNodeOriginTransport.map(source, value -> value);

		assertThat(reads).as("mapping waits for no statement").hasValue(0);
		assertThat(mapped.getNamespaces()).containsExactlyEntriesOf(Map.of("ex", "urn:ex:"));
		assertThat(reads).hasValue(1);
		assertThat(mapped.next()).isEqualTo(statement);
	}

	@Test
	void aHeaderFailureSurfacesWhenTheMappedResultIsReadNotWhenItIsMapped() {
		TupleQueryResult tuples = new IteratingTupleQueryResult(List.of(), List.<BindingSet>of()) {
			@Override
			public List<String> getBindingNames() {
				throw new QueryEvaluationException("no header");
			}
		};
		GraphQueryResult graph = new IteratingGraphQueryResult(Map.of(), List.<Statement>of()) {
			@Override
			public Map<String, String> getNamespaces() {
				throw new QueryEvaluationException("no statements");
			}
		};

		TupleQueryResult mappedTuples = BNodeOriginTransport.map(tuples, value -> value);
		GraphQueryResult mappedGraph = BNodeOriginTransport.map(graph, value -> value);

		assertThatThrownBy(mappedTuples::getBindingNames).hasMessageContaining("no header");
		assertThatThrownBy(mappedGraph::getNamespaces).hasMessageContaining("no statements");
	}

	@Test
	void aNegotiatedBackgroundTupleResultReturnsBeforeTheServerSendsItsHeader() throws Exception {
		Factory factory = new Factory();
		factory.stored.add("raw-id");
		Value wire = BNodeOriginTransport.encoder(factory).apply(factory.createBNode("raw-id"));
		PipedOutputStream server = new PipedOutputStream();
		PipedInputStream body = new PipedInputStream(server, 1 << 16);

		try (RDF4JProtocolSession session = session(TupleQueryResultFormat.BINARY.getDefaultMIMEType(), body);
				PipedOutputStream answer = server) {
			TupleQueryResult result = assertTimeoutPreemptively(PROMPTLY,
					() -> session.getBackgroundTupleQueryResult(request(), null),
					"evaluate() must not wait for the result header");

			answer.write(tupleBytes(wire, wire));
			answer.close();

			assertThat(result.getBindingNames()).containsExactly("node");
			List<BindingSet> rows = new ArrayList<>();
			result.forEach(rows::add);
			assertThat(rows).hasSize(2).allSatisfy(row -> {
				RepositoryBNode node = (RepositoryBNode) row.getValue("node");
				assertThat(node.getRawID()).isEqualTo("raw-id");
				assertThat(node.isReference()).isTrue();
			});
			result.close();
		}
	}

	@Test
	void aNegotiatedBackgroundGraphResultReturnsBeforeTheServerSendsItsFirstStatement() throws Exception {
		Factory factory = new Factory();
		factory.stored.add("stored-subject");
		Value subject = BNodeOriginTransport.encoder(factory).apply(factory.createBNode("stored-subject"));
		PipedOutputStream server = new PipedOutputStream();
		PipedInputStream body = new PipedInputStream(server, 1 << 16);

		try (RDF4JProtocolSession session = session(RDFFormat.BINARY.getDefaultMIMEType(), body);
				PipedOutputStream answer = server) {
			GraphQueryResult result = assertTimeoutPreemptively(PROMPTLY,
					() -> session.getRDFBackground(request(), false, null),
					"evaluate() must not wait for the first statement");

			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			RDFWriter writer = Rio.createWriter(RDFFormat.BINARY, bytes);
			writer.startRDF();
			writer.handleNamespace("ex", "urn:ex:");
			writer.handleStatement(VF.createStatement((BNode) subject, VF.createIRI("urn:ex:p"), VF.createLiteral(1)));
			writer.endRDF();
			answer.write(bytes.toByteArray());
			answer.close();

			assertThat(result.getNamespaces()).containsEntry("ex", "urn:ex:");
			Statement statement = result.next();
			RepositoryBNode decoded = (RepositoryBNode) statement.getSubject();
			assertThat(decoded.getRawID()).isEqualTo("stored-subject");
			assertThat(decoded.isReference()).isTrue();
			assertThat(result.hasNext()).isFalse();
			result.close();
		}
	}

	@Test
	void aBrokenResponseBeforeTheHeaderFailsTheResultInsteadOfEvaluate() throws Exception {
		PipedOutputStream server = new PipedOutputStream();
		PipedInputStream body = new PipedInputStream(server, 1 << 16);

		try (RDF4JProtocolSession session = session(TupleQueryResultFormat.BINARY.getDefaultMIMEType(), body);
				PipedOutputStream answer = server) {
			TupleQueryResult result = assertTimeoutPreemptively(PROMPTLY,
					() -> session.getBackgroundTupleQueryResult(request(), null));

			answer.write(new byte[] { 'n', 'o', 't', ' ', 'b', 'i', 'n', 'a', 'r', 'y' });
			answer.close();

			assertThatThrownBy(() -> {
				result.getBindingNames();
				result.hasNext();
			}).isInstanceOf(QueryEvaluationException.class);
			result.close();
		}
	}

	private RDF4JProtocolSession session(String contentType, InputStream body) throws IOException {
		HttpResponse response = mock(HttpResponse.class);
		when(response.getStatusCode()).thenReturn(200);
		List<HttpHeader> headers = new ArrayList<>();
		headers.add(HttpHeader.of("Content-Type", contentType));
		headers.add(HttpHeader.of(BNodeOriginTransport.HEADER, BNodeOriginTransport.VERSION));
		when(response.getHeaders()).thenReturn(headers);
		when(response.getHeaders("Content-Type")).thenReturn(List.of(HttpHeader.of("Content-Type", contentType)));
		when(response.getHeader("Content-Type")).thenReturn(Optional.of(contentType));
		when(response.getHeader(BNodeOriginTransport.HEADER)).thenReturn(Optional.of(BNodeOriginTransport.VERSION));
		when(response.getBodyAsStream()).thenReturn(body);
		RDF4JHttpClient client = mock(RDF4JHttpClient.class);
		when(client.execute(any())).thenReturn(response);
		RDF4JProtocolSession session = new RDF4JProtocolSession(client, executor);
		session.setQueryURL("http://example.org/repositories/test");
		session.setBNodeOriginEnabled(true);
		return session;
	}

	private static HttpRequest request() {
		return HttpRequests.get("http://example.org/repositories/test").build();
	}

	private static byte[] tupleBytes(Value... nodes) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(bytes);
		writer.startQueryResult(List.of("node"));
		for (Value node : nodes) {
			writer.handleSolution(row("node", node));
		}
		writer.endQueryResult();
		return bytes.toByteArray();
	}

	private static BindingSet row(String name, Value value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, value);
		return row;
	}
}
